#include <string.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_ADDR_BUFFER 1024

bool extract_sockaddr_from_url(const char* url, char** sockaddr_url, char** sockaddr_port) {
    char* proto_end = strstr((char*)url, "://");
    if (!proto_end) {
        return false;
    }

    char* url_start = proto_end + 3;
    char* colon = strchr(url_start, ':');

    if (!colon) {
        // No port specified, default to port 80
        *sockaddr_port = strdup("80");
        if (!*sockaddr_port) {
            return false;
        }
    } else {
        // Port specified, extract it
        size_t port_len = 0;
        char* end_of_url = strchr(colon + 1, '/');
        if (end_of_url) {
            port_len = end_of_url - colon;
        } else {
            port_len = strlen(colon);
        }

        *sockaddr_port = strndup(colon + 1, port_len);
        if (!*sockaddr_port) {
            return false;
        }
    }

    // Now extract the address
    char* open_bracket = strchr(url_start, '[');
    char* close_bracket = (open_bracket) ? strchr(open_bracket + 1, ']') : NULL;

    if (open_bracket && close_bracket && (close_bracket < colon)) {
        // IPv6 format
        size_t address_len = close_bracket - url_start;
        if (address_len > MAX_ADDR_BUFFER) {
            address_len = MAX_ADDR_BUFFER;
            // Optionally log warning here
        }
        *sockaddr_url = strndup(url_start, address_len);
    } else {
        // IPv4 or invalid format
        size_t address_len = 0;
        if (colon) {
            address_len = colon - url_start;
        } else {
            address_len = strlen(url_start);
        }

        if (address_len > MAX_ADDR_BUFFER) {
            address_len = MAX_ADDR_BUFFER;
            // Optionally log warning here
        }

        *sockaddr_url = strndup(url_start, address_len);
    }

    if (!*sockaddr_url) {
        return false;
    }

    return true;
}

#include <string.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdio.h>

#define MAX_BUFFER_SIZE 1024

bool extract_sockaddr_from_url(char* url, char** sockaddr_url, char** sockaddr_port) {
    char* protocol_end = strstr(url, "://");
    if (!protocol_end) {
        return false;
    }

    char* address_start = protocol_end + 3;
    char* port_start = strchr(address_start, ':');

    // Handle IPv6 address within brackets
    if (*address_start == '[') {
        char* bracket_end = strchr(address_start, ']');
        if (!bracket_end) {
            return false;
        }
        *bracket_end = '\0';
        port_start = bracket_end + 1;
        if (port_start && *port_start == ':') {
            port_start++;
        }
    }

    if (!port_start) {
        port_start = NULL;
    }

    size_t address_length = port_start ? (size_t)(port_start - address_start) : strlen(address_start);

    // Truncate if necessary
    if (address_length > MAX_BUFFER_SIZE - 1) {
        fprintf(stderr, "Warning: Address exceeds buffer size and has been truncated.\n");
        address_length = MAX_BUFFER_SIZE - 1;
    }

    *sockaddr_url = (char*)malloc(address_length + 1);
    if (!*sockaddr_url) {
        return false;
    }
    strncpy(*sockaddr_url, address_start, address_length);
    (*sockaddr_url)[address_length] = '\0';

    if (port_start) {
        size_t port_length = strlen(port_start);
        *sockaddr_port = (char*)malloc(port_length + 1);
        if (!*sockaddr_port) {
            free(*sockaddr_url);
            return false;
        }
        strncpy(*sockaddr_port, port_start, port_length + 1);
    } else {
        *sockaddr_port = (char*)malloc(3);
        if (!*sockaddr_port) {
            free(*sockaddr_url);
            return false;
        }
        strcpy(*sockaddr_port, "80");
    }

    return true;
}

#include <string.h>
#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>

#define MAX_ADDR_BUFFER_SIZE 1024

bool extract_sockaddr_from_url(const char* url, char** sockaddr_url, char** sockaddr_port) {
    // Validate inputs
    if (!url || !sockaddr_url || !sockaddr_port) {
        return false;
    }

    // Default port
    char* default_port = "80";
    char* port = NULL;
    char* address = NULL;

    // Find the colon to split address and port
    char* url_copy = strdup(url);
    if (!url_copy) {
        return false;
    }

    char* colon = strrchr(url_copy, ':');
    if (colon) {
        // Handle IPv6 if enclosed in brackets
        if (colon[1] && colon[-1] == ']') {
            // Port is after the closing bracket
            char* port_start = colon + 1;
            *colon = '\0';
            port = strdup(port_start);
        } else {
            // Port is at the end of the string
            *colon = '\0';
            port = strdup(colon + 1);
        }
    }

    // Allocate buffer for address
    size_t url_len = strlen(url_copy);
    size_t alloc_size = url_len < MAX_ADDR_BUFFER_SIZE ? url_len + 1 : MAX_ADDR_BUFFER_SIZE + 1;

    address = (char*)malloc(alloc_size);
    if (!address) {
        free(url_copy);
        return false;
    }

    // Copy or truncate address to fit buffer
    strncpy(address, url_copy, alloc_size - 1);
    address[alloc_size - 1] = '\0';

    if (url_len >= MAX_ADDR_BUFFER_SIZE) {
        printf("Warning: Address truncated to fit buffer size.\n");
    }

    // Assign results to output parameters
    *sockaddr_url = address;
    *sockaddr_port = port ? port : default_port;

    // Clean up
    free(url_copy);
    return true;
}

#include <string.h>
