#include <stdbool.h>

#define MAX_BUFFER_SIZE 1024

bool extract_sockaddr_from_url(const char* url, char** sockaddr_url, char** sockaddr_port) {
    const char* protocol_start = "http://";
    const char* protocol_start_https = "https://";
    char* url_copy = strdup(url);
    char* url_ptr = url_copy;

    // Check for protocol
    if (strncmp(url_ptr, protocol_start, strlen(protocol_start)) == 0) {
        url_ptr += strlen(protocol_start);
    } else if (strncmp(url_ptr, protocol_start_https, strlen(protocol_start_https)) == 0) {
        url_ptr += strlen(protocol_start_https);
    } else {
        free(url_copy);
        return false;
    }

    // Skip until address
    char* address_start = url_ptr;

    // Check for IPv6 (with brackets)
    if (*address_start == '[') {
        address_start++;
        char* ipv6_end = strchr(address_start, ']');
        if (!ipv6_end) {
            free(url_copy);
            return false;
        }

        // Check if port follows after the closing bracket
        if (ipv6_end[1] == ':') {
            // Extract port
            char* port_start = ipv6_end + 2;
            char* port_end = strchr(port_start, '/');
            if (!port_end) {
                port_end = port_start + strlen(port_start);
            }

            // Allocate port string
            size_t port_length = port_end - port_start;
            *sockaddr_port = (char*)malloc(port_length + 1);
            if (!*sockaddr_port) {
                free(url_copy);
                return false;
            }
            strncpy(*sockaddr_port, port_start, port_length);
            (*sockaddr_port)[port_length] = '\0';

            // Truncate address if it exceeds MAX_BUFFER_SIZE
            size_t address_length = ipv6_end - address_start;
            if (address_length >= MAX_BUFFER_SIZE) {
                address_length = MAX_BUFFER_SIZE - 1;
                // Log warning here if necessary
            }

            *sockaddr_url = (char*)malloc(address_length + 1);
            if (!*sockaddr_url) {
                free(url_copy);
                free(*sockaddr_port);
                return false;
            }

            strncpy(*sockaddr_url, address_start, address_length);
            (*sockaddr_url)[address_length] = '\0';

            free(url_copy);
            return true;
        }
    } else {
        // IPv4 case
        char* port_separator = strchr(address_start, ':');
        if (port_separator) {
            // Extract port
            char* port_start = port_separator + 1;
            char* port_end = strchr(port_start, '/');
            if (!port_end) {
                port_end = port_start + strlen(port_start);
            }

            size_t port_length = port_end - port_start;
            *sockaddr_port = (char*)malloc(port_length + 1);
            if (!*sockaddr_port) {
                free(url_copy);
                return false;
            }
            strncpy(*sockaddr_port, port_start, port_length);
            (*sockaddr_port)[port_length] = '\0';

            // Extract address up to port separator
            size_t address_length = port_separator - address_start;
            if (address_length >= MAX_BUFFER_SIZE) {
                address_length = MAX_BUFFER_SIZE - 1;
                // Log warning here if necessary
            }

            *sockaddr_url = (char*)malloc(address_length + 1);
            if (!*sockaddr_url) {
                free(url_copy);
                free(*sockaddr_port);
                return false;
            }
            strncpy(*sockaddr_url, address_start, address_length);
            (*sockaddr_url)[address_length] = '\0';
        } else {
            // Default port 80
            *sockaddr_url = (char*)malloc(strlen(address_start) + 1);
            if (!*sockaddr_url) {
                free(url_copy);
                return false;
            }
            strcpy(*sockaddr_url, address_start);

            *sockaddr_port = (char*)malloc(3);
            if (!*sockaddr_port) {
                free(url_copy);
                free(*sockaddr_url);
                return false;
            }
            strcpy(*sockaddr_port, "80");
        }

        free(url_copy);
        return true;
    }

    free(url_copy);
    return false;
}

#include <string.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdio.h>

#define MAX_BUFFER_SIZE 1024

bool extract_sockaddr_from_url(char* url, char** sockaddr_url, char** sockaddr_port) {
    char* protocol_end = strstr(url, "://");
    if (!protocol_end) {
        return false;
    }

    char* host_part = protocol_end + 3;
    char* address_end = strchr(host_part, ':');
    char* port_start = NULL;

    if (address_end && address_end[1] == ']') {
        // IPv6 address
        char* bracket_end = strchr(address_end, ']');
        if (!bracket_end) {
            return false;
        }
        *bracket_end = '\0';
        port_start = bracket_end + 2;
        *bracket_end = ']';
    } else {
        // IPv4 address
        if (address_end) {
            port_start = address_end + 1;
        }
    }

    size_t url_len = strlen(host_part);
    if (address_end && url_len > (size_t)(address_end - host_part)) {
        url_len = (size_t)(address_end - host_part);
    }

    if (url_len > MAX_BUFFER_SIZE) {
        url_len = MAX_BUFFER_SIZE;
        fprintf(stderr, "Warning: Socket address truncated to fit buffer size.\n");
    }

    *sockaddr_url = (char*)malloc(url_len + 1);
    if (!(*sockaddr_url)) {
        return false;
    }
    strncpy(*sockaddr_url, host_part, url_len);
    (*sockaddr_url)[url_len] = '\0';

    if (port_start && *port_start) {
        size_t port_len = strlen(port_start);
        *sockaddr_port = (char*)malloc(port_len + 1);
        if (!(*sockaddr_port)) {
            free(*sockaddr_url);
            *sockaddr_url = NULL;
            return false;
        }
        strncpy(*sockaddr_port, port_start, port_len);
        (*sockaddr_port)[port_len] = '\0';
    } else {
        *sockaddr_port = (char*)malloc(3 + 1);
        if (!(*sockaddr_port)) {
            free(*sockaddr_url);
            *sockaddr_url = NULL;
            return false;
        }
        strncpy(*sockaddr_port, "80", 3);
        (*sockaddr_port)[3] = '\0';
    }

    return true;
}
